// ===== Data model: types and interfaces =====

export type Department = "CSE" | "IT" | "AI&DS" | "ECE" | "EEE" | "MECH" | "CIVIL";
export type Year = 1 | 2 | 3 | 4;

export const DEPARTMENTS: readonly Department[] = [
  "CSE",
  "IT",
  "AI&DS",
  "ECE",
  "EEE",
  "MECH",
  "CIVIL",
];

export interface Student {
  id: string;
  rollNo: string;
  name: string;
  email: string;
  phone: string;
  department: Department;
  year: Year;
  marks: number; // percentage out of 100
}

// What the form gives us (id is generated by the service)
export type StudentInput = Omit<Student, "id">;

export const PASS_MARK = 40;

export function getGrade(marks: number): string {
  if (marks >= 90) return "O";
  if (marks >= 80) return "A+";
  if (marks >= 70) return "A";
  if (marks >= 60) return "B+";
  if (marks >= 50) return "B";
  if (marks >= PASS_MARK) return "C";
  return "F";
}
